const securise = (nom) => {
  try {
    return $(nom).all().map((i) => i.json).filter((j) => j && !j.error)
  } catch (e) {
    return []
  }
}
return [{
  json: {
    semaine: $now.setLocale('fr').toFormat("'semaine du' d LLLL yyyy"),
    calls: securise('Calls de la semaine'),
    activite: securise('Activité cockpit'),
  },
}]
